cypress_script:
describe('Accordion Functionality', () => {
  it('should expand the first accordion section', () => {
    cy.visit('https://demoqa.com/accordian');
    cy.get('button.accordion-button').contains('What is Lorem Ipsum?').click();
    cy.url().should('eq', 'https://demoqa.com/accordian');
  });

  it('should not expand any other sections when the first is collapsed', () => {
    cy.visit('https://demoqa.com/accordian');
    cy.get('button.accordion-button').contains('What is Lorem Ipsum?').click();
    cy.get('button.accordion-button.collapsed').contains('Where does it come from?').should('be.visible');
    cy.get('button.accordion-button.collapsed').contains('Why do we use it?').should('be.visible');
    cy.url().should('eq', 'https://demoqa.com/accordian');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Accordion Functionality', () => {
  test('should expand the first accordion section', async ({ page }) => {
    await page.goto('https://demoqa.com/accordian');
    await page.locator('button.accordion-button').withText('What is Lorem Ipsum?').click();
    await expect(page).toHaveURL('https://demoqa.com/accordian');
  });

  test('should not expand any other sections when the first is collapsed', async ({ page }) => {
    await page.goto('https://demoqa.com/accordian');
    await page.locator('button.accordion-button').withText('What is Lorem Ipsum?').click();
    await expect(page.locator('button.accordion-button.collapsed').withText('Where does it come from?')).toBeVisible();
    await expect(page.locator('button.accordion-button.collapsed').withText('Why do we use it?')).toBeVisible();
    await expect(page).toHaveURL('https://demoqa.com/accordian');
  });
});
